// Shelf-life estimates from USDA FSIS FoodKeeper (public domain). Data: src/data/foodkeeper.json,
// generated by scripts/build-foodkeeper.py.
import data from './data/foodkeeper.json';

type Product = {
  n: string; // name
  s?: string; // subtitle, e.g. "whole" or "canned evaporated or condensed"
  k?: string[]; // keywords
  c?: string; // category
  p?: number; f?: number; z?: number; // days in pantry / fridge / freezer
  po?: number; fo?: number; // days after opening in pantry / fridge
};

const PRODUCTS = data as Product[];

// Subtitle words that describe a special form of the food. They count against a match
// unless the item name says the same thing ("milk" shouldn't match "milk, canned evaporated").
const SPECIAL = new Set(['canned', 'can', 'cooked', 'homemade', 'dried', 'dry', 'frozen', 'jar', 'jars', 'shelf', 'stable',
  'smoked', 'pickled', 'opened', 'mix', 'leftover', 'evaporated', 'condensed', 'ultra', 'pasteurized', 'ultrapasteurized',
  'prepared', 'powdered', 'instant', 'stuffed', 'breaded', 'extract', 'juice', 'sauce']);

const words = (t: string) => t.toLowerCase().split(/[^a-z]+/).filter(Boolean);
// Crude singular form so "bananas"/"banana" and "berries"/"berry" meet.
const stem = (w: string) => (w.endsWith('ies') ? w.slice(0, -3) + 'y' : w.endsWith('oes') ? w.slice(0, -2) : w.endsWith('s') && !w.endsWith('ss') ? w.slice(0, -1) : w);
const stems = (t: string) => new Set(words(t).map(stem));

const INDEX = PRODUCTS.map((p) => ({
  p,
  // "Carrots, parsnips" names two foods; match either one.
  alts: p.n.split(',').map((a) => [...stems(a)]).filter((a) => a.length),
  name: stems(p.n),
  sub: stems(p.s ?? ''),
  keys: new Set((p.k ?? []).flatMap(words).map(stem)),
}));

const cache = new Map<string, Product | null>();

export function matchFood(name: string): Product | null {
  const key = name.trim().toLowerCase();
  if (cache.has(key)) return cache.get(key)!;
  const item = stems(key);
  const head = stem(words(key).at(-1) ?? ''); // "oat milk" is a kind of milk
  let best: Product | null = null;
  let bestScore = 0;
  for (const e of INDEX) {
    // The product's own name counts most: a full match gets a bonus, extra name words cost,
    // and matching the item's head noun beats matching a modifier.
    let score = 0;
    for (const alt of e.alts) {
      const hit = alt.filter((w) => item.has(w)).length;
      if (!hit) continue;
      const s = hit * 4 + (hit === alt.length ? 6 : 0) - (alt.length - hit) * 3 + (alt.at(-1) === head ? 4 : 0);
      score = Math.max(score, s);
    }
    for (const w of item) {
      if (e.keys.has(w)) score += 3;
      if (e.sub.has(w)) score += 2;
      // Words in the item this product says nothing about ("breast" vs "chicken, whole").
      if (!e.name.has(w) && !e.keys.has(w) && !e.sub.has(w)) score -= 3;
    }
    for (const w of new Set([...e.name, ...e.sub])) if (SPECIAL.has(w) && !item.has(w)) score -= 5;
    // Unmatched descriptor words make an entry more specific than asked for (capped).
    score -= Math.min(2, [...e.sub].filter((w) => !item.has(w)).length * 0.5);
    // Ties go to the more generic entry (fewer keywords).
    score -= (e.p.k?.length ?? 0) * 0.01;
    if (score > bestScore) { bestScore = score; best = e.p; }
  }
  const out = bestScore >= 3 ? best : null;
  cache.set(key, out);
  return out;
}

// Locations other than fridge/freezer (pantry, garage shelf, …) are treated as room temperature.
export function shelfLifeDays(name: string, loc: string): number | null {
  const m = matchFood(name);
  if (!m) return null;
  if (loc === 'freezer') return m.z ?? null;
  if (loc === 'fridge') return m.f ?? null;
  return m.p ?? null;
}

export function openedLifeDays(name: string, loc: string): number | null {
  const m = matchFood(name);
  if (!m) return null;
  return loc === 'fridge' ? (m.fo ?? null) : loc === 'freezer' ? null : (m.po ?? m.fo ?? null);
}
